const std = @import("std");
pub fn build(b: *std.Build) void {
    const source = b.option([]const u8, "boundary-source", "Frozen Boundary source") orelse
        @panic("provide -Dboundary-source");
    const legacy = b.option(bool, "legacy-names", "Frozen predecessor module names") orelse false;
    const data_name = if (legacy) "boundary_data_v2" else "boundary_data";
    const data = b.createModule(.{
        .root_source_file = .{ .cwd_relative = b.pathJoin(&.{ source, "src/v2/data/root.zig" }) },
        .target = b.graph.host,
        .optimize = .ReleaseSafe,
    });
    const boundary = b.createModule(.{
        .root_source_file = .{ .cwd_relative = b.pathJoin(&.{ source, "src/v2/root.zig" }) },
        .target = b.graph.host,
        .optimize = .ReleaseSafe,
        .imports = &.{.{ .name = data_name, .module = data }},
    });
    const root = b.createModule(.{
        .root_source_file = b.path("producer.zig"),
        .target = b.graph.host,
        .optimize = .ReleaseSafe,
        .imports = &.{.{ .name = "boundary", .module = boundary }},
    });
    b.installArtifact(b.addExecutable(.{ .name = "producer", .root_module = root }));
}

