const std = @import("std");
const boundary = @import("boundary");
const current = @hasDecl(boundary, "data");
const data = if (current) boundary.data else boundary.data_v2;
const count: usize = 64;
pub fn main(init: std.process.Init) !void {
    var args = std.process.Args.Iterator.init(init.minimal.args);
    _ = args.next();
    const format = args.next() orelse return error.MissingFormat;
    if (args.next() != null) return error.UnexpectedArgument;
    if (!std.mem.eql(u8, format, if (current) "bpi3" else "bpi2") and
        (current or !std.mem.eql(u8, format, "bpc1"))) return error.InvalidFormat;
    var builder = boundary.source.Builder.init(init.gpa);
    defer builder.deinit();
    var compiled = try boundary.program.compile(init.gpa, try boundary.source.examples.installations(&builder, count));
    defer compiled.deinit();
    const compact = std.mem.eql(u8, format, "bpc1");
    const length = if (current) try data.program_image.encodedLength(compiled.program) else if (compact) try data.compact_image.encodedLength(init.gpa, compiled.program) else try data.image.encodedLength(compiled.program);
    const bytes = try init.gpa.alloc(u8, length);
    defer init.gpa.free(bytes);
    if (current) {
        _ = try compiled.encode(init.gpa, bytes);
    } else if (compact) {
        _ = try data.compact_image.encode(init.gpa, compiled.program, bytes);
    } else _ = try compiled.encode(init.gpa, bytes);
    var buffer: [4096]u8 = undefined;
    var output = std.Io.File.stdout().writer(init.io, &buffer);
    try output.interface.writeAll(bytes);
    try output.interface.flush();
}

