import assert from 'node:assert/strict';
import{mkdirSync,cpSync,readFileSync,writeFileSync,statSync}from'node:fs';
import{execFileSync,spawnSync}from'node:child_process';
import{join}from'node:path';
import{pathToFileURL}from'node:url';
import{createHash}from'node:crypto';
const d=import.meta.dirname;
const beforeModule=await import(pathToFileURL(process.env.BASELINE_AGENT + '/runtime/world.mjs'));
const afterModule=await import(pathToFileURL(join(d,'agent/runtime/world.mjs')));
const hosts={before:await beforeModule.loadWorldRuntime({runtimePath:process.env.BASELINE_RUNTIME}),after:await afterModule.loadWorldRuntime({runtimePath:process.env.CURRENT_RUNTIME})};
const digest=b=>createHash('sha256').update(b).digest('hex');
const rows=[];
function timed(command,args,cwd,log){const start=process.hrtime.bigint();const result=spawnSync(command,args,{cwd,encoding:null,maxBuffer:8<<20,timeout:180000});const ns=Number(process.hrtime.bigint()-start);writeFileSync(log,result.stderr??Buffer.alloc(0));assert.equal(result.status,0,result.stderr?.toString());return{ns,bytes:result.stdout};}
async function emit(exe,format,count,cwd,phase){const calls=[];let bytes,firstProcessNanoseconds;
 for(let i=0;i<7;i++){const out=timed(exe,[format],cwd,join(cwd,phase+'-'+format+'-emit.log'));if(i===0)firstProcessNanoseconds=out.ns;if(bytes)assert.equal(digest(out.bytes),digest(bytes));else bytes=out.bytes;if(i>=2)calls.push(out.ns);}
 const outcome=await hosts[format==='bpi3'?'after':'before'].start(bytes,new Uint8Array());assert.equal(outcome.kind.toLowerCase(),'completed');assert.equal(outcome.value.length,8);assert.equal(new DataView(outcome.value.buffer,outcome.value.byteOffset,8).getBigUint64(0,true),BigInt(count*(count+1)/2));
 writeFileSync(join(cwd,phase+'.'+format),bytes);return{format,count,bytes:bytes.length,sha256:digest(bytes),firstProcessNanoseconds,processNanoseconds:calls,expected:count*(count+1)/2};}
for(let window=0;window<2;window++)for(let round=0;round<2;round++)for(const variant of((window+round)%2?['after','before']:['before','after'])){
 const root=join(d,`series1-producer-${window}-${round}-${variant}`);mkdirSync(root);cpSync(join(d,'driver'),join(root,'driver'),{recursive:true});const local=join(root,'local'),global=join(root,'global'),out=join(root,'out');mkdirSync(local);mkdirSync(global);
 const args=['build','--build-file',join(root,'driver/build.zig'),'-Dboundary-source='+join(d,'boundary-'+variant),...(variant==='before'?['-Dlegacy-names=true']:[]),'--cache-dir',local,'--global-cache-dir',global,'--prefix',out,'-j4','--summary','all'];
 const formats=variant==='before'?['bpi2','bpc1']:['bpi3'];const record={window,round,variant,commands:{build:['zig',...args]},phases:{}};
 for(const phase of ['cold','warm','client-edit']){
  if(phase==='client-edit'){const p=join(root,'driver/producer.zig');const original=readFileSync(p,'utf8');assert(original.includes('const count: usize = 64;'));writeFileSync(p,original.replace('const count: usize = 64;','const count: usize = 65;'));}
  const built=timed('zig',args,root,join(root,phase+'-build.log'));const executable=join(out,'bin/producer');const emissions=[];for(const f of formats)emissions.push(await emit(executable,f,phase==='client-edit'?65:64,root,phase));record.phases[phase]={nativeBuildNanoseconds:built.ns,executableBytes:statSync(executable).size,emissions};
  console.log(JSON.stringify({window,round,variant,phase,nativeBuildMs:built.ns/1e6,images:emissions.map(e=>({format:e.format,bytes:e.bytes}))}));
 }
 rows.push(record);writeFileSync(join(d,'series1-producer-results.json'),JSON.stringify({method:'Four observations per revision: two rounds in each of two alternating windows. Cold means empty Zig compile caches, not a cold OS file cache. Native build and prebuilt producer process clocks are separate. Each emission uses two warmups and five process samples; every image is byte-stable and executes to the independent expected sum.',rows},null,2)+'\n');
}

