import assert from'node:assert/strict';
import{cpSync,mkdirSync,readFileSync,writeFileSync,existsSync,statSync}from'node:fs';
import{spawnSync}from'node:child_process';import{join}from'node:path';import{pathToFileURL}from'node:url';import{createHash}from'node:crypto';
const d=import.meta.dirname,hash=b=>createHash('sha256').update(b).digest('hex');
const {loadWorldRuntime}=await import(pathToFileURL(join(d,'agent/runtime/world.mjs')));
const host=await loadWorldRuntime({runtimePath:process.env.CURRENT_RUNTIME});
const u64=n=>{const b=new Uint8Array(8);new DataView(b.buffer).setBigUint64(0,BigInt(n),true);return b;};
function timed(cmd,args,cwd,log){const start=process.hrtime.bigint(),r=spawnSync(cmd,args,{cwd,maxBuffer:8<<20,timeout:240000});const ns=Number(process.hrtime.bigint()-start);writeFileSync(log,r.stderr??Buffer.alloc(0));assert.equal(r.status,0,r.stderr?.toString());return{ns,bytes:r.stdout,stderr:r.stderr.toString()};}
async function verify(bytes,mode,bonus=0,counter=41){let out=await host.start(bytes,mode.startsWith('agent')?u64(100):new Uint8Array()),yields=0,releases=0;const sum=counter*2+1;for(let i=0;i<16;i++){
 if(out.kind==='completed'){assert.equal(yields,1);assert.equal(releases,1);assert.deepEqual(out.value,u64(mode==='double'?sum*2:sum+(mode.startsWith('agent')?100+bonus+(mode==='agent-next'?1:0):0)));return;}
 if(out.kind==='yielded'){yields++;out=await host.continueExecution(bytes,out);}
 else{assert.equal(out.kind,'requested');const {request}=await host.inspectPending(out);assert.equal(request.semanticIdentity,'component/release');assert.deepEqual(request.payload,u64(sum));releases++;out=await host.resume(bytes,out.state,out.request,new Uint8Array());}
 }throw Error('Fixture failed to terminate');}
async function link(exe,mode,area,phase,bonus,counter){const samples=[];let bytes,first;for(let i=0;i<7;i++){const r=timed(exe,[mode],area,join(area,phase+'-'+mode+'.log'));const observed=JSON.parse(r.stderr);assert.deepEqual(observed,{sourceChecks:mode.startsWith('agent')?1:0,lowerings:mode.startsWith('agent')?1:0});if(bytes)assert.equal(hash(bytes),hash(r.bytes));else{bytes=r.bytes;first=r.ns;}if(i>=2)samples.push(r.ns);}await verify(bytes,mode,bonus,counter);writeFileSync(join(area,phase+'-'+mode+'.bpi3'),bytes);return{mode,bytes:bytes.length,sha256:hash(bytes),firstProcessNanoseconds:first,samplesNanoseconds:samples,sourceChecks:mode.startsWith('agent')?1:0,lowerings:mode.startsWith('agent')?1:0};}
const rows=[];
for(let window=0;window<2;window++){
 const root=join(d,'series1-components-'+window);mkdirSync(root);const agent=join(root,'agent');cpSync(join(d,'agent'),agent,{recursive:true});const global=join(root,'global'),local=join(root,'local'),prefix=join(root,'out'),area=join(root,'objects');for(const p of[global,local,area])mkdirSync(p);
 // Acquire only the authenticated source package before the native-build clock.
 const fetched=timed('zig',['fetch','--global-cache-dir',global,process.env.BOUNDARY_ARCHIVE],agent,join(root,'fetch.log'));
 assert.equal(fetched.bytes.toString().trim(),JSON.parse(readFileSync(join(agent,'conformance/agent4/dependencies.lock.json'))).boundary.package.zigHash);
 const args=['build','build-component-tools','-Doptimize=ReleaseSafe','-j4','--cache-dir',local,'--global-cache-dir',global,'--prefix',prefix,'--summary','all'];
 const cold=timed('zig',args,agent,join(root,'cold-build.log'));assert(!existsSync(join(agent,'.agent4')),'authoring target must not install World');
 const emitter=join(prefix,'bin/agent4-component-objects'),linker=join(prefix,'bin/agent4-component-link');const emitterHash=hash(readFileSync(emitter));const objects={},emissionCounts={};
 for(const[file,kind]of[['call','call'],['state','state'],['suspend','suspended'],['double','double']]){const r=timed(emitter,[kind],area,join(root,'emit-'+file+'.log'));assert.equal(r.bytes.subarray(0,8).toString(),'ABL_BMO1');writeFileSync(join(area,file+'.bmo1'),r.bytes);objects[file]={bytes:r.bytes.length,sha256:hash(r.bytes),firstEmissionNanoseconds:r.ns};emissionCounts[file]=1;}
 const initial=[];for(const mode of['standalone','double','agent','agent-next'])initial.push(await link(linker,mode,area,'initial',0,41));
 const warm=timed('zig',args,agent,join(root,'warm-build.log'));
 const clientPath=join(agent,'test/agent4/component_link.zig'),clientSource=readFileSync(clientPath,'utf8');const anchor='Application.increment = @intFromBool(std.mem.eql(u8, mode, "agent-next"));';assert.equal(clientSource.split(anchor).length,2);writeFileSync(clientPath,clientSource.replace(anchor,'Application.increment = 1 + @as(u64, @intFromBool(std.mem.eql(u8, mode, "agent-next")));'));
 const edited=timed('zig',args,agent,join(root,'client-edit-build.log'));assert.equal(hash(readFileSync(emitter)),emitterHash);assert.match(edited.stderr,/compile exe agent4-component-objects[^\n]*cached/);
 const client=await link(linker,'agent',area,'client-edit',1,41);assert.notEqual(client.sha256,initial.find(x=>x.mode==='agent').sha256);for(const[name,obj]of Object.entries(objects))assert.equal(hash(readFileSync(join(area,name+'.bmo1'))),obj.sha256);
 // The component owner rebuilds from one changed source literal. The client
 // binary and all other component bytes remain fixed across this boundary.
 const boundary=join(root,'component-boundary'),driver=join(root,'component-driver');cpSync(join(d,'boundary-after'),boundary,{recursive:true});mkdirSync(driver);
 let build=readFileSync(join(d,'driver/build.zig'),'utf8').replace('b.path("producer.zig")','.{ .cwd_relative = b.pathJoin(&.{ source, "tools/component_example.zig" }) }').replace('.name = "producer"','.name = "component-producer"');writeFileSync(join(driver,'build.zig'),build);
 const componentArgs=['build','--build-file',join(driver,'build.zig'),'-Dboundary-source='+boundary,'--cache-dir',join(root,'component-local'),'--global-cache-dir',global,'--prefix',join(root,'component-out'),'-j4','--summary','all'];
 const ownerBuild=timed('zig',componentArgs,root,join(root,'component-owner-build.log'));
 const componentSource=join(boundary,'src/v2/source/component_examples.zig'),original=readFileSync(componentSource,'utf8');assert.equal(original.split('try b.constant(u64, 41)').length,2);writeFileSync(componentSource,original.replace('try b.constant(u64, 41)','try b.constant(u64, 43)'));
 const rebuilt=timed('zig',componentArgs,root,join(root,'component-edit-build.log'));
 const componentExe=join(root,'component-out/bin/component-producer');const produced=timed(componentExe,['state'],area,join(root,'component-rebuild-emit.log'));assert.notEqual(hash(produced.bytes),objects.state.sha256);writeFileSync(join(area,'state.bmo1'),produced.bytes);emissionCounts.state++;
 for(const name of['call','suspend','double'])assert.equal(hash(readFileSync(join(area,name+'.bmo1'))),objects[name].sha256);
 const clientHash=hash(readFileSync(linker)),relinked=[];for(const mode of['standalone','agent'])relinked.push(await link(linker,mode,area,'component-edit',1,43));assert.equal(hash(readFileSync(linker)),clientHash);assert.deepEqual(emissionCounts,{call:1,state:2,suspend:1,double:1});
 const row={window,nativeBuildNanoseconds:{cold:cold.ns,warm:warm.ns,clientEdit:edited.ns,componentOwnerInitial:ownerBuild.ns,componentEdit:rebuilt.ns},nativeExecutableBytes:{emitter:statSync(emitter).size,client:statSync(linker).size},objects,emissionCounts,initial,clientEdit:{sourceDelta:'increment += 1',unchangedEmitterSha256:emitterHash,client},componentEdit:{sourceDelta:'initial private counter41->43',objectBytes:produced.bytes.length,objectSha256:hash(produced.bytes),emissionNanoseconds:produced.ns,unchangedClientSha256:clientHash,relinked}};
 rows.push(row);writeFileSync(join(d,'component-results.json'),JSON.stringify({method:'Two independent cold workflows; empty Zig compile caches, package acquisition excluded and recorded, no World installed into authoring checkout. Native builds timed separately from prebuilt emitter/client/link processes. Each link mode uses two warmups and five timed processes. Every image executes with independent expected result and cleanup payload.',rows},null,2)+'\n');console.log(JSON.stringify({window,nativeBuildMilliseconds:Object.fromEntries(Object.entries(row.nativeBuildNanoseconds).map(([k,n])=>[k,n/1e6])),emissionCounts}));
}
